$ErrorActionPreference = "Stop"

$backend = "C:\Projects\SmartTimetable\backend"
$target = Join-Path $backend "apps\scheduling\engine\application\timetable_persistence.py"
$backupDir = Join-Path $backend "audit_backups"

New-Item -ItemType Directory -Force -Path $backupDir | Out-Null

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path $backupDir ("timetable_persistence.py_before_grade10_shared_block_fix_" + $stamp + ".py")

if (-not (Test-Path $target)) {
    throw "Target file not found: $target"
}

Copy-Item $target $backup -Force

$base64 = @'

'@

$bytes = [System.Convert]::FromBase64String($base64)
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$updated = $utf8NoBom.GetString($bytes)

[System.IO.File]::WriteAllText($target, $updated, $utf8NoBom)

Write-Host "============================================================"
Write-Host "GRADE 10 PERSISTENCE SHARED-BLOCK FIX"
Write-Host "============================================================"
Write-Host "TARGET : $target"
Write-Host "BACKUP : $backup"
Write-Host ""

python -m py_compile $target
if ($LASTEXITCODE -ne 0) {
    throw "Python compile check failed."
}

Write-Host "PYTHON COMPILE CHECK: PASS"
Write-Host ""

python manage.py check
if ($LASTEXITCODE -ne 0) {
    throw "Django check failed."
}

Write-Host ""
Write-Host "DJANGO CHECK: PASS"
Write-Host ""
Write-Host "PERSISTENCE FILE REPLACED SUCCESSFULLY"
